# Import pandas library to handle structured tabular data (dataframes)
import pandas as pd

# Import train_test_split to divide data into training and testing sets
from sklearn.model_selection import train_test_split

# Import Random Forest Classifier, an ensemble machine learning algorithm
from sklearn.ensemble import RandomForestClassifier

# Import accuracy_score to evaluate the model's performance percentage
from sklearn.metrics import accuracy_score

def run_pipeline():
    # Step 1: Read the Titanic dataset CSV file into a pandas DataFrame named 'df'
    # Load the Titanic dataset directly from a clean public URL
    url = 'https://raw.githubusercontent.com/plotly/datasets/master/titanic.csv'
    df = pd.read_csv(url)

    # # 1. Load raw dataset from local data directory
    #     dataset_path = 'data/titanic.csv'
    #     df = pd.read_csv(dataset_path)

    print('First 5 records:')
    print(df.head())

    """**# Input Features (Information used to predict survival)**

    * PassengerId: A unique ID number assigned to each
    row (usually dropped during training as it has no predictive value).
    * Pclass (Passenger Class): Ticket class indicating socioeconomic status.   
      1.   1st Class (Upper)
      2.   2nd Class (Middle)   
      3.   3rd Class (Lower)   

    * Name: Full name of the passenger (includes titles like Mr., Mrs., Miss, Master).   
    * Sex: Gender of the passenger (male or female).   
    * Age: Passenger age in years.   
    * SibSp: Number of Siblings / Spouses traveling with the passenger.   
    * Parch: Number of Parents / Children traveling with the passenger.   
    * Ticket: Ticket number string.   
    * Fare: Amount of money paid for the ticket.   
    * Cabin: Cabin room number (contains NaN if missing/unrecorded).   
    * Embarked: Port where the passenger boarded the ship:   
      1. S = Southampton   
      2. C = Cherbourg   
      3. Q = Queenstown   
    """

    # 1. Convert 'Sex' column into numbers: female = 1, male = 0
    df['Sex_Numeric'] = df['Sex'].map({'female': 1, 'male': 0})

    """![image.png](data:image/png;base64,)"""

    # Step 2: Select Features (X) and Target (y)
    # Extract feature variables (X) and fill missing values (NaN) with 0
    x = df[['Pclass', 'Fare', 'Age', 'Sex_Numeric']].fillna(0)
    x

    y = df['Survived']
    y

    # Step 3. Train the exact same model
    # This line splits your dataset into two separate sets: one set for teaching the model (Training) and one set for testing the model (Testing).

    # If you test a model on the exact same data it learned from,
    # it's like giving a student the exam questions with the answers before
    # the test—they will score 100%, but they haven't actually learned how to solve new problems.
    x_train, x_test, y_train, y_test = train_test_split(
        x, y, test_size=0.2, random_state=42
    )

    """![image.png](data:image/png;base64,)"""

    # 4. Train the Random Forest Model
    model = RandomForestClassifier()
    model.fit(x_train, y_train)

    """![image.png](data:image/png;base64,)

    ![image.png](data:image/png;base64,)
    """

    # 5. Make predictions and print accuracy
    predictions = model.predict(x_test)
    print(f'Model Accuracy: {accuracy_score(y_test, predictions) * 100:.2f}%')

    """![image.png](data:image/png;base64,)

    ![image.png](data:image/png;base64,)

    ![image.png](data:image/png;base64,)
    """


if __name__ == '__main__':
    run_pipeline()
# This block ensures that run_pipeline() executes only when you run the script directly, but not when another file imports it.

# How It Works
# When you run the file directly (python src/train_pipeline.py):
# Python automatically sets the hidden variable __name__ to '__main__'. The condition evaluates to True, so run_pipeline() executes immediately.

# When another script imports this file (import train_pipeline):
# Python sets __name__ to 'train_pipeline' (the file name). The condition evaluates to False, preventing the training process from running automatically upon import.

# Why Use It?
# It keeps your code modular and reusable. You can safely import helper functions or classes from train_pipeline.py into other scripts (like an API server or test suite) without accidentally triggering model training every time.